parameters.jsCode:
const leads = $('Lead Metrikleri').all();
const linkedin = $('LinkedIn Son Veri').first()?.json || {};

const typeLabels = { quote: 'Teklif', contact: 'İletişim', callback: 'Geri Arama', newsletter: 'Bülten', linkedin_lead: 'LinkedIn Lead' };

const totalLeads = leads.reduce((sum, item) => sum + parseInt(item.json.count), 0);

const leadRows = leads.map(item => {
  const label = typeLabels[item.json.type] || item.json.type;
  return `<tr><td>${label}</td><td style="text-align:center">${item.json.count}</td></tr>`;
}).join('');

const now = new Date().toLocaleDateString('tr-TR');
const weekAgo = new Date(Date.now() - 7*24*60*60*1000).toLocaleDateString('tr-TR');

const html = `
<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px">
<h2 style="color:#1e3a5f">📊 Haftalık Performans Raporu</h2>
<p style="color:#666">${weekAgo} — ${now}</p>

<h3 style="color:#1e3a5f">Lead Özeti (${totalLeads} toplam)</h3>
<table style="width:100%;border-collapse:collapse">
<tr style="background:#1e3a5f;color:white"><th style="padding:8px;text-align:left">Tür</th><th style="padding:8px">Adet</th></tr>
${leadRows}
</table>

<h3 style="color:#1e3a5f">LinkedIn İstatistikleri</h3>
<table style="width:100%;border-collapse:collapse">
<tr style="background:#0077b5;color:white"><th style="padding:8px;text-align:left">Metrik</th><th style="padding:8px">Değer</th></tr>
<tr><td style="padding:8px">Takipçi</td><td style="padding:8px;text-align:center">${linkedin.followers || '-'}</td></tr>
<tr style="background:#f5f5f5"><td style="padding:8px">Gösterim</td><td style="padding:8px;text-align:center">${linkedin.impressions || '-'}</td></tr>
<tr><td style="padding:8px">Tıklama</td><td style="padding:8px;text-align:center">${linkedin.clicks || '-'}</td></tr>
<tr style="background:#f5f5f5"><td style="padding:8px">Etkileşim</td><td style="padding:8px;text-align:center">%${linkedin.engagement || '-'}</td></tr>
</table>

<p style="color:#999;font-size:12px;margin-top:20px">Alo Yönetim n8n Otomasyonu — ${now}</p>
</body></html>`;

const telegramText = `📊 *Haftalık Rapor*\n\n📋 Toplam Lead: ${totalLeads}\n${leads.map(l => `• ${typeLabels[l.json.type] || l.json.type}: ${l.json.count}`).join('\n')}\n\n💼 LinkedIn:\n👥 Takipçi: ${linkedin.followers || '-'}\n👁️ Gösterim: ${linkedin.impressions || '-'}\n📈 Etkileşim: %${linkedin.engagement || '-'}`;

return [{ json: { html, telegramText, totalLeads } }];

